1	import { useQuery } from '@tanstack/react-query';
2	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
3	import type { ContentfulClientApi } from 'contentful';
4	import { useContentfulClient } from './useContentfulClient';
5	import { filterByRegion, pickMostSpecificByRegion } from '../utils/resolveByRegion';
6	import { CONTENT_TYPE_IDS } from '../config/contentfulMapping';
7	import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
8	import type { HeaderNavigationEntry, HeaderNavItemEntry } from '../types/contentful';
9	
10	// Contentful resolves nested references `include` levels deep, and the header nav model is
11	// one level deeper than the footer's: headerNavigation → items (1) → columns (2) → links (3)
12	// → link.regions (4). See footer/index.tsx's FOOTER_INCLUDE_DEPTH comment for what getting
13	// this wrong looks like (an under-resolved `regions` reference arrives as an unresolvable
14	// link stub with no `fields`, which throws when read).
15	const HEADER_NAV_INCLUDE_DEPTH = 4;
16	
17	const HEADER_NAV_QUERY_KEY = 'headerNavigation';
18	
19	type UseHeaderNavResult = {
20	  /** Region-resolved header nav items for the current storefront. `undefined` only while the
21	   *  fetch is in flight — once settled (success, error, or no entry for this region) this is
22	   *  always an array, empty if there's nothing to show, so a consumer's loading indicator
23	   *  doesn't spin forever waiting for a value that will never arrive. */
24	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
25	  isLoading: boolean;
26	  isError: boolean;
27	};
28	
29	// useMultiSite ships untyped from the base SFCC package — same cast FooterContainer already
30	// uses for this exact lookup.
31	type MultiSiteResult = { site: { id: string }; locale?: { id: string } };
32	
33	/**
34	 * Fetches the `headerNavigation` root entry from Contentful and resolves the region-scoped
35	 * entry for the current storefront, mirroring how `FooterContainer`
36	 * (overrides/app/components/footer/index.tsx) resolves `footerConfig` — same
37	 * `pickMostSpecificByRegion` root-resolution step, plus a `filterByRegion` pass over the
38	 * resolved entry's `items` array so each item's own `regions` field (per-item market
39	 * scoping, see headerNavItem.js) actually has an effect.
40	 *
41	 * Uses `@tanstack/react-query`'s `useQuery` rather than the footer's raw `useEffect`/
42	 * `useState` — the app already mounts a `QueryClientProvider` for every page via
43	 * `withReactQuery(AppConfig, ...)` in `_app-config`, so this needs no provider of its own.
44	 *
45	 * @returns the current storefront's resolved header nav items, plus query status flags.
46	 *   `items` is `undefined` while loading, on fetch failure, or when no entry resolves for
47	 *   this region — callers should treat that the same as "nothing to render yet," matching
48	 *   FooterContainer's "renders nothing" behaviour on an unresolved fetch.
49	 */
50	export const useHeaderNav = (): UseHeaderNavResult => {
51	  const { site, locale: siteLocale } = useMultiSite() as MultiSiteResult;
52	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
53	  const { client } = useContentfulClient();
54	
55	  const { data, isLoading, isError } = useQuery({
56	    queryKey: [HEADER_NAV_QUERY_KEY, site.id, locale],
57	    queryFn: async () => {
58	      // Guaranteed non-null: `enabled: !!client` below means this only runs once a client
59	      // exists, but TypeScript can't see that gate from inside the closure.
60	      // `useContentfulClient` types the client as `ContentfulClientApi<any>` for the
61	      // Experiences SDK's benefit — with `any` chain modifiers, `EntriesQueries`'s
62	      // `locale` field resolves out of the type entirely (see its `WITH_ALL_LOCALES`
63	      // conditional), so narrow back to the real default (`undefined`) modifiers here.
64	      const entries = await (client as ContentfulClientApi<undefined>)!.getEntries({
65	        content_type: CONTENT_TYPE_IDS.headerNavigation,
66	        include: HEADER_NAV_INCLUDE_DEPTH,
67	        locale,
68	      });
69	      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
70	      // HeaderNavigationEntry mirrors the exact nested-resolved shape `include: 4`
71	      // produces for this content model.
72	      return entries.items as unknown as HeaderNavigationEntry[];
73	    },
74	    enabled: !!client,
75	  });
76	
77	  const resolved = data ? pickMostSpecificByRegion<HeaderNavigationEntry>(data, site.id) : undefined;
78	  const items = isLoading
79	    ? undefined
80	    : resolved
81	    ? filterByRegion<HeaderNavItemEntry>(resolved.fields.items, site.id)
82	    : [];
83	
84	  return { items, isLoading, isError };
85	};
86

1	import { describe, test, expect, vi, beforeEach } from 'vitest';
2	import { waitFor } from '@testing-library/react';
3	import { renderHookWithQueryClient } from '../test-utils/renderWithProviders';
4	import { useHeaderNav } from './useHeaderNav';
5	import type { HeaderNavigationEntry, HeaderNavItemEntry, RegionEntry } from '../types/contentful';
6	
7	const mockGetEntries = vi.fn();
8	
9	vi.mock('./useContentfulClient', () => ({
10	  useContentfulClient: () => ({ client: { getEntries: mockGetEntries }, previewUnavailable: false, isPreview: false }),
11	}));
12	
13	let mockSiteId = 'ZimmermannAU';
14	let mockLocaleId: string | undefined = 'en-AU';
15	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
16	  default: () => ({ site: { id: mockSiteId }, locale: mockLocaleId ? { id: mockLocaleId } : undefined }),
17	}));
18	
19	const region = (siteId: string): RegionEntry => ({
20	  sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' } } },
21	  fields: { siteId, label: siteId },
22	});
23	
24	const navItem = (id: string, overrides: Partial<HeaderNavItemEntry['fields']> = {}): HeaderNavItemEntry => ({
25	  sys: { id, contentType: { sys: { id: 'headerNavItem' } } },
26	  fields: { label: id, ...overrides },
27	});
28	
29	const headerNav = (id: string, items: HeaderNavItemEntry[], regions?: RegionEntry[]): HeaderNavigationEntry => ({
30	  sys: { id, contentType: { sys: { id: 'headerNavigation' } } },
31	  fields: { internalTitle: id, items, regions },
32	});
33	
34	describe('useHeaderNav', () => {
35	  beforeEach(() => {
36	    vi.clearAllMocks();
37	    mockSiteId = 'ZimmermannAU';
38	    mockLocaleId = 'en-AU';
39	  });
40	
41	  test('resolves the most specific region-scoped headerNavigation entry over the global default', async () => {
42	    const globalItem = navItem('global-item');
43	    const auOnlyItem = navItem('au-item');
44	    const globalEntry = headerNav('global', [globalItem]);
45	    const auEntry = headerNav('au-scoped', [auOnlyItem], [region('ZimmermannAU')]);
46	
47	    mockGetEntries.mockResolvedValue({ items: [globalEntry, auEntry] });
48	
49	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
50	
51	    await waitFor(() => expect(result.current.isLoading).toBe(false));
52	
53	    expect(result.current.items).toEqual([auOnlyItem]);
54	  });
55	
56	  test("filters the resolved entry's items by each item's own regions field", async () => {
57	    const globalItem = navItem('global-item');
58	    const auItem = navItem('au-item', { regions: [region('ZimmermannAU')] });
59	    const usItem = navItem('us-item', { regions: [region('ZimmermannUS')] });
60	    const entry = headerNav('global', [globalItem, auItem, usItem]);
61	
62	    mockGetEntries.mockResolvedValue({ items: [entry] });
63	
64	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
65	
66	    await waitFor(() => expect(result.current.isLoading).toBe(false));
67	
68	    expect(result.current.items).toEqual([globalItem, auItem]);
69	  });
70	
71	  test('returns an empty array, not undefined, once settled with no entry eligible for the current region', async () => {
72	    // undefined must mean "still loading" only — a consumer's spinner (aria-busy tied to
73	    // isLoading) would otherwise spin forever once the fetch has actually settled.
74	    const usOnlyEntry = headerNav('us-scoped', [navItem('us-item')], [region('ZimmermannUS')]);
75	    mockGetEntries.mockResolvedValue({ items: [usOnlyEntry] });
76	
77	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
78	
79	    await waitFor(() => expect(result.current.isLoading).toBe(false));
80	
81	    expect(result.current.items).toEqual([]);
82	  });
83	
84	  test('passes the headerNavigation content type, include depth 4, and the active locale to the Contentful client', async () => {
85	    mockGetEntries.mockResolvedValue({ items: [] });
86	
87	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
88	
89	    await waitFor(() => expect(result.current.isLoading).toBe(false));
90	
91	    expect(mockGetEntries).toHaveBeenCalledWith({
92	      content_type: 'headerNavigation',
93	      include: 4,
94	      locale: 'en-AU',
95	    });
96	  });
97	
98	  test('falls back to the default Contentful locale when useMultiSite has no locale yet', async () => {
99	    mockLocaleId = undefined;
100	    mockGetEntries.mockResolvedValue({ items: [] });
101	
102	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
103	
104	    await waitFor(() => expect(result.current.isLoading).toBe(false));
105	
106	    expect(mockGetEntries).toHaveBeenCalledWith(expect.objectContaining({ locale: 'en-US' }));
107	  });
108	});
109

1	import React, { useCallback, useMemo, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
3	import { Button } from '@salesforce/retail-react-app/app/components/shared/ui';
4	import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';
5	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
6	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
7	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
8	import { navLinks } from '@salesforce/retail-react-app/app/pages/account/constant';
9	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
10	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
11	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
12	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
13	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
14	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
15	import { useUiCopy } from 'app/hooks/useUiCopy';
16	import { MegaMenuOpenContext } from 'app/hooks/useMegaMenuOpenReporter';
17	import { useHeaderMenuExpandedState } from 'app/hooks/useHeaderMenuExpandedState';
18	import { DrawerMenuStateContext } from 'app/hooks/useDrawerMenuState';
19	import type { MenuExpandedState } from './headerTypes';
20	import { LeftBar } from './leftBar';
21	import { RightBar } from './rightBar';
22	
23	type HeaderProps = {
24	  children?: React.ReactNode;
25	  onMenuClick?: () => void;
26	  onLogoClick?: () => void;
27	  onMyAccountClick?: () => void;
28	  onWishlistClick?: () => void;
29	  onMyCartClick?: () => void;
30	  onStoreLocatorClick?: () => void;
31	  onAgentClick?: () => void;
32	  searchInputRef?: React.Ref<HTMLInputElement>;
33	  [key: string]: unknown;
34	};
35	
36	type NavLink = {
37	  name: string;
38	  path: string;
39	  icon: React.ComponentType<{ boxSize: number }>;
40	};
41	
42	type OneClickCheckoutConfig = {
43	  enabled?: boolean;
44	};
45	
46	// Height derived from header.css.ts's logoBar padding, per design: logoBar is capped at
47	// 114px total (desktop/tablet) / 66px total (mobile), padding-bottom 48px/40px respectively,
48	// padding-top 0 — so logo height is 66px desktop/tablet, 26px mobile. Width is 'auto', not
49	// fixed, so it follows the wordmark's native aspect ratio at that height (no distortion, no
50	// letterboxing). Set here rather than in header.css.ts's `Header` recipe: Chakra's multi-part
51	// recipe merge silently loses an override to base SFCC's own `logo` part here.
52	// audit-allow: literal design-spec value, no named token exists for it.
53	const HEADER_LOGO_SX: SystemStyleObject = {
54	  // Overrides ZimmLogo's own maxWidth: 327px default, which would otherwise cap this.
55	  maxWidth: 'none',
56	  width: 'auto',
57	  height: { base: '26px', sm: '26px', md: '74px', lg: '74px', xl: '74px', '2xl': '74px' },
58	};
59	
60	// Outer horizontal padding, sourced from the shared --zimm-grid-margin-*/--zimm-grid-max-width
61	// tokens (gridSystem.ts) rather than hardcoded here — same values apply to footer and the
62	// main content area, one place to change all three. Set directly on this div rather than
63	// through header.css.ts's `Header` recipe, for the same reason as HEADER_LOGO_SX above:
64	// Chakra's multi-part recipe merge doesn't reliably let an override win against base SFCC's
65	// own `content` part here.
66	const HEADER_CONTENT_SX: SystemStyleObject = {
67	  maxWidth: 'var(--zimm-grid-max-width)',
68	  marginLeft: 0,
69	  marginRight: 0,
70	  paddingTop: 0,
71	  paddingBottom: 0,
72	  paddingLeft: {
73	    base: 'var(--zimm-grid-margin-mobile)',
74	    sm: 'var(--zimm-grid-margin-mobile)',
75	    md: 'var(--zimm-grid-margin-tablet)',
76	    lg: 'var(--zimm-grid-margin-tablet)',
77	    xl: 'var(--zimm-grid-margin-desktop)',
78	    '2xl': 'var(--zimm-grid-margin-desktop)',
79	  },
80	  paddingRight: {
81	    base: 'var(--zimm-grid-margin-mobile)',
82	    sm: 'var(--zimm-grid-margin-mobile)',
83	    md: 'var(--zimm-grid-margin-tablet)',
84	    lg: 'var(--zimm-grid-margin-tablet)',
85	    xl: 'var(--zimm-grid-margin-desktop)',
86	    '2xl': 'var(--zimm-grid-margin-desktop)',
87	  },
88	};
89	
90	/**
91	 * Search bar for the header.
92	 *
93	 * The search bar is a simple input field with a search icon.
94	 * It can be used to search for products or navigate to a
95	 * specific page.
96	 *
97	 * @param props {object} the component props
98	 * @returns {Element} the search bar element
99	 */
100	// const SearchBar = (props: Record<string, unknown>) => {
101	//   const styles = useMultiStyleConfig('Header');
102	//   const intl = useIntl();
103	//   const placeholder = intl.formatMessage({
104	//     id: 'header.field.placeholder.search_for_products',
105	//     defaultMessage: 'Search for products...',
106	//   });
107	//   return (
108	//     <Box {...styles.searchContainer}>
109	//       <Search aria-label={placeholder} placeholder={placeholder} {...styles.search} {...props} />
110	//     </Box>
111	//   );
112	// };
113	
114	/**
115	 * Header shell — fetches commerce data and distributes it as props to LeftBar and RightBar.
116	 * Renders a two-row layout: topBar row (nav + icons) + logoBar row.
117	 *
118	 * Layout sub-components:
119	 *   - LeftBar (leftBar/index.tsx): hamburger on mobile, desktop nav at tablet+
120	 *   - RightBar (rightBar/index.tsx): search + icon buttons on desktop, search/bag on mobile
121	 *
122	 * To customize styles:
123	 *   - Shell layout (topBar, logoBar): header/header.css.ts
124	 *   - Left nav group: header/leftBar/leftBar.css.ts (ZimmHeaderLeftBar)
125	 *   - Right section:  header/rightBar/rightBar.css.ts (ZimmHeaderRightBar)
126	 *
127	 * @param props see HeaderProps
128	 */
129	const Header = ({
130	  children,
131	  onMenuClick = noop,
132	  onMyAccountClick = noop,
133	  onLogoClick = noop,
134	  onMyCartClick = noop,
135	  onWishlistClick = noop,
136	  onStoreLocatorClick = noop,
137	  onAgentClick = noop,
138	  searchInputRef,
139	  ...props
140	}: HeaderProps) => {
141	  const { t } = useUiCopy();
142	  const {
143	    derivedData: { totalItems },
144	    data: basket,
145	  } = useCurrentBasket();
146	  const { isRegistered } = useCustomerType();
147	  // SFCC's own native wish_list customer product list (CRM-025: wishlist data stored in SFCC
148	  // today; ENH-038/039's SFCC-vs-Omneo hosting question is about future enhancements, not this
149	  // current storage). Disabled for guests internally (no customerId), so this is always `false`
150	  // pre-login. Same hook the base SFCC wishlist account page and PR #83's ZimmWishlistAuthDrawer
151	  // work already build on — no new integration introduced here.
152	  const { data: wishList } = useWishList();
153	  const hasWishlistItems = (wishList?.customerProductListItems?.length ?? 0) > 0;
154	  const logout = useAuthHelper(AuthHelpers.Logout);
155	  const navigate = useNavigation();
156	  const appConfig = getConfig().app;
157	  const storeLocatorEnabled = (appConfig?.storeLocatorEnabled as boolean | undefined) ?? STORE_LOCATOR_IS_ENABLED;
158	  const commerceAgentConfig = getCommerceAgentConfig();
159	  const showLaunchAgentButton = commerceAgentConfig?.enableAgentFromHeader === 'true';
160	  const [showLoading, setShowLoading] = useState(false);
161	  const { oneClickCheckout = {} } = appConfig as { oneClickCheckout?: OneClickCheckoutConfig };
162	  const isOneClickCheckoutEnabled = oneClickCheckout.enabled;
163	
164	  // Desktop/tablet mega-menu open state (SFCC-96) — drives RightBar's 'fullSwap' Close-control
165	  // swap. `reportOpen` hands us the popover's real `onClose`, so `closeMegaMenu` can actually
166	  // close it (not just flip this mirror state). Menu stays open until Close is clicked, a leaf
167	  // link is followed, or Escape — no close-on-hover-out/outside-click.
168	  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
169	  const megaMenuCloseRef = useRef<(() => void) | null>(null);
170	  const reportMegaMenuOpen = useCallback((onClose: () => void) => {
171	    megaMenuCloseRef.current = onClose;
172	    setIsMegaMenuOpen(true);
173	  }, []);
174	  const reportMegaMenuClosed = useCallback(() => {
175	    megaMenuCloseRef.current = null;
176	    setIsMegaMenuOpen(false);
177	  }, []);
178	  const closeMegaMenu = useCallback(() => {
179	    megaMenuCloseRef.current?.();
180	  }, []);
181	  const megaMenuOpenReporter = useMemo(
182	    () => ({ reportOpen: reportMegaMenuOpen, reportClose: reportMegaMenuClosed }),
183	    [reportMegaMenuOpen, reportMegaMenuClosed],
184	  );
185	
186	  // Mobile L1/L2 drawer state (SFCC-97). Base `_app`'s `useDisclosure` passes `onMenuClick`
187	  // (its `onOpen`) to Header directly, but `isOpen`/`onClose` go straight to the sibling
188	  // `<DrawerMenu>` it renders as Header's own `children` — Header has no `onClose` prop of
189	  // its own. `useHeaderMenuExpandedState` owns the depth (closed/L1/L2) state this shell needs
190	  // for LeftBar/RightBar's `menuExpanded`, and `DrawerMenuStateContext` (provided around
191	  // `children` below) is how the nested DrawerMenu and this shell share it without Header
192	  // needing to know `_app.jsx`'s exact children shape — see both hooks' own JSDoc.
193	  const {
194	    menuExpanded: mobileMenuExpanded,
195	    handleMenuClick,
196	    handleBack,
197	    handleClose,
198	    contextValue,
199	  } = useHeaderMenuExpandedState(onMenuClick);
200	
201	  // Combined menuExpanded for LeftBar/RightBar (see headerTypes.ts): the desktop/tablet
202	  // mega-menu ('fullSwap') and the mobile drawer ('mobileL1'/'mobileL2') are mutually
203	  // exclusive by breakpoint in practice (LeftBar/RightBar's own recipes hide one control set
204	  // per breakpoint), but both pieces of state genuinely coexist in this shell — SFCC-96 owns
205	  // `isMegaMenuOpen`, SFCC-97 owns `mobileMenuExpanded`. Mobile state takes precedence when
206	  // active; otherwise fall through to the desktop mega-menu state. `onCloseMenu` below picks
207	  // the matching close handler the same way, so RightBar's single `onClose` prop always closes
208	  // whichever one is actually open.
209	  const menuExpanded: MenuExpandedState =
210	    mobileMenuExpanded !== 'closed' ? mobileMenuExpanded : isMegaMenuOpen ? 'fullSwap' : 'closed';
211	  const onCloseMenu = mobileMenuExpanded !== 'closed' ? handleClose : closeMegaMenu;
212	
213	  // Filter navigation links based on 1CC configuration
214	  const filteredNavLinks = isOneClickCheckoutEnabled
215	    ? (navLinks as NavLink[])
216	    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');
217	
218	  const onSignout = async () => {
219	    if (showLoading) return;
220	    setShowLoading(true);
221	    try {
222	      await logout.mutateAsync();
223	      navigate('/login');
224	    } finally {
225	      setShowLoading(false);
226	    }
227	  };
228	
229	  const styles = useMultiStyleConfig('Header');
230	
231	  return (
232	    <MegaMenuOpenContext.Provider value={megaMenuOpenReporter}>
233	      <chakra.header __css={styles.container} role="banner" {...props}>
234	        <chakra.div __css={HEADER_CONTENT_SX}>
235	          {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
236	
237	          {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
238	          <chakra.div __css={styles.topBar}>
239	            <LeftBar onMenuClick={handleMenuClick} menuExpanded={menuExpanded} onBack={handleBack}>
240	              <DrawerMenuStateContext.Provider value={contextValue}>{children}</DrawerMenuStateContext.Provider>
241	            </LeftBar>
242	            <RightBar
243	              hasBasket={!!basket}
244	              totalItems={totalItems}
245	              isRegistered={isRegistered}
246	              hasWishlistItems={hasWishlistItems}
247	              filteredNavLinks={filteredNavLinks}
248	              showLaunchAgentButton={showLaunchAgentButton}
