246	AppConfig.restore = (locals: AppLocals = {}): void => {
247	  const path =
248	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
249	
250	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
251	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
252	  // by matching the locale alias from the URL against each site's supportedLocales.
253	  const defaultResolved = resolveSiteFromUrl(path);
254	  const { localeRef } = getParamsFromPath(path);
255	  type SupportedLocale = { id: string; alias?: string };
256	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
257	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
258	  type Site = {
259	    id: string;
260	    sfccSiteId?: string;
261	    alias?: string;
262	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
263	  };
264	  const site: Site = localeRef
265	    ? (getSites() as Site[]).find((s) =>
266	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
267	      ) ?? defaultResolved
268	    : defaultResolved;
269	
270	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
271	  // site too. Resolve the locale directly from the site we already found above.
272	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
273	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
274	
275	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
276	  const apiConfig = {
277	    ...appConfig.commerceAPI,
278	    einsteinConfig: appConfig.einsteinAPI,
279	  };
280	
281	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
282	
283	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
284	  locals.site = site;
285	  locals.locale = locale;
286	  locals.appConfig = appConfig;
287	};
288	
289	AppConfig.freeze = (): undefined => undefined;
290	
291	AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
292	  return {
293	    buildUrl: locals.buildUrl,
294	    site: locals.site,
295	    locale: locals.locale,
296	  };
297	};
