305	  queryClientConfig: {
306	    defaultOptions: {
307	      queries: {
308	        retry: false,
309	        refetchOnWindowFocus: false,
310	        staleTime: 10 * 1000,
311	        ...(isServerSide ? { retryOnMount: false } : {}),
312	      },
313	      mutations: {
314	        retry: false,
315	      },
316	    },
317	  },
318	};
319	
320	export default withReactQuery(AppConfig, options);
