1	import type { HeaderNavItemEntry, NavGroupEntry } from 'app/types/contentful';
2	import { resolveImageEntry } from 'app/utils/resolveImageEntry';
3	import type { MegaMenuItem, MegaMenuSection } from './types';
4	
5	/** `ListMenuPopover`/base `ListMenuContent` share a generic `item[itemsKey]` contract —
6	 *  `itemsKey` is always `'columns'` for a `headerNavItem` in practice, but arrives as a plain
7	 *  string to match that contract rather than a hardcoded literal. */
8	type FieldsWithSections = Record<string, ReadonlyArray<NavGroupEntry> | undefined> & {
9	  twoColumnLayout?: boolean;
10	};
11	
12	const toSection = (group: NavGroupEntry): MegaMenuSection => {
13	  // An empty/whitespace-only heading is Contentful's "unheaded group" shape (the curated
14	  // groups seen under "New" have no heading) — treated the same as an omitted heading, not
15	  // rendered as a blank heading element.
16	  const heading = group.fields.heading?.trim();
17	
18	  return {
19	    heading: heading ? heading : undefined,
20	    links: group.fields.links.map((link) => ({
21	      label: link.fields.label,
22	      href: link.fields.href,
23	    })),
24	  };
25	};
