3	export type HeaderNavTriggerElement = HTMLAnchorElement | HTMLButtonElement | null;
4	
5	export type HeaderNavKeyboardControls = {
6	  /** Ref callback to attach to the L1 trigger element at `index` (its `<a>`/`<button>`, not a
7	   *  wrapping `<Box>` — arrow-key focus targets the real focusable node directly). */
8	  getTriggerRef: (index: number) => (node: HeaderNavTriggerElement) => void;
9	  /** Keydown handler to attach to the same element, alongside `getTriggerRef`. */
10	  onTriggerKeyDown: (index: number) => (event: React.KeyboardEvent) => void;
11	};
12	
13	/**
14	 * Left/Right/Home/End roving focus across the header's L1 nav triggers — a supplementary
15	 * keyboard accelerator layered on top of native Tab order, per ARIA APG's Disclosure
16	 * Navigation pattern (https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/):
17	 * no `menu`/`menubar`/`menuitem` roles (those are for application menus, not site navigation —
18	 * using them here would make a screen reader announce "N items" as if entering an app menu),
19	 * and no `tabIndex` manipulation — every L1 trigger stays its own independent Tab stop, exactly
20	 * like a plain nav list, so nothing changes about how Tab already behaves.
21	 *
22	 * @returns see HeaderNavKeyboardControls
23	 */
24	export const useHeaderNavKeyboard = (): HeaderNavKeyboardControls => {
25	  const triggerRefs = useRef<HeaderNavTriggerElement[]>([]);
26	
27	  const getTriggerRef = useCallback(
28	    (index: number) => (node: HeaderNavTriggerElement) => {
29	      triggerRefs.current[index] = node;
30	    },
31	    [],
32	  );
33	
34	  const focusIndex = useCallback((index: number) => {
35	    triggerRefs.current[index]?.focus();
36	  }, []);
37	
38	  const onTriggerKeyDown = useCallback(
39	    (index: number) => (event: React.KeyboardEvent) => {
40	      const count = triggerRefs.current.length;
41	      if (count === 0) return;
42	
43	      switch (event.key) {
44	        case 'ArrowRight':
45	          event.preventDefault();
46	          focusIndex((index + 1) % count);
47	          break;
48	        case 'ArrowLeft':
49	          event.preventDefault();
50	          focusIndex((index - 1 + count) % count);
51	          break;
52	        case 'Home':
53	          event.preventDefault();
54	          focusIndex(0);
55	          break;
56	        case 'End':
57	          event.preventDefault();
58	          focusIndex(count - 1);
59	          break;
60	        default:
61	          break;
62	      }
63	    },
64	    [focusIndex],
65	  );
66	
67	  return { getTriggerRef, onTriggerKeyDown };
68	};
