1	import type { ImageEntry } from 'app/types/contentful';
2	
3	export type ResolvedImage = {
4	  src: string;
5	  alt: string;
6	};
7	
8	/**
9	 * Resolves a Contentful `image` entry (the reusable asset + accessible-metadata primitive —
10	 * see ImageEntry's own doc comment) down to the `{src, alt}` shape every `<Image>` render site
11	 * actually needs. Shared by megaMenuContent/toMegaMenuItem.ts (desktop/tablet) and
12	 * drawer-menu/index.tsx (mobile L2) — both resolve the same field shape.
13	 *
14	 * `decorative` short-circuits to an empty alt (screen readers skip it) regardless of whether
15	 * `altText` also happens to be set — an editor marking an image decorative is asserting no
16	 * fallback is warranted, not just skipping the field. Absent decorative/altText, falls back to
17	 * the underlying asset's own description/title, matching this field's pre-migration behaviour
18	 * when it linked a raw Asset directly.
19	 *
20	 * @param image the `promoImage`-shaped field value, or undefined if unset
21	 * @returns the resolved `{src, alt}`, or undefined if no image/asset is actually linked
22	 */
23	export const resolveImageEntry = (image: ImageEntry | undefined): ResolvedImage | undefined => {
24	  const asset = image?.fields.asset;
25	  if (!asset) return undefined;
26	
27	  const alt = image.fields.decorative ? '' : image.fields.altText ?? asset.fields.description ?? asset.fields.title;
28	
29	  return { src: asset.fields.file.url, alt };
30	};
